//! Official known-answer vectors in `test_data/kat_sources`, generated by
//! `test_data/scripts/import_kat_sources.py` (OpenSSL 3.1.2 test data, NIST CAVP, Wycheproof).
//! Used only by tests, in this crate and in the crates that consume the KMS crypto layer.

use std::path::Path;

use serde::{Deserialize, Deserializer, de::DeserializeOwned};

use crate::{CryptoError, error::result::CryptoResult};

/// AES-CMAC (empty `iv`, `tag` possibly truncated) or AES-GMAC (`msg` is the authenticated data) vector.
#[derive(Debug, Clone, Deserialize)]
pub struct MacVector {
    /// Unique vector id.
    pub id: String,
    /// Where the vector comes from.
    pub source: String,
    /// AES key.
    #[serde(deserialize_with = "from_hex")]
    pub key: Vec<u8>,
    /// 12-byte GMAC IV; empty for CMAC.
    #[serde(default, deserialize_with = "from_hex")]
    pub iv: Vec<u8>,
    /// Message (CMAC) or authenticated data (GMAC).
    #[serde(deserialize_with = "from_hex")]
    pub msg: Vec<u8>,
    /// Expected tag.
    #[serde(deserialize_with = "from_hex")]
    pub tag: Vec<u8>,
    /// `false` if the tag must be rejected.
    pub valid: bool,
}

/// AES-GCM vector with a 12-byte IV and a 16-byte tag.
#[derive(Debug, Clone, Deserialize)]
pub struct AeadVector {
    /// Unique vector id.
    pub id: String,
    /// Where the vector comes from.
    pub source: String,
    /// AES key.
    #[serde(deserialize_with = "from_hex")]
    pub key: Vec<u8>,
    /// 12-byte IV.
    #[serde(deserialize_with = "from_hex")]
    pub iv: Vec<u8>,
    /// Additional authenticated data.
    #[serde(deserialize_with = "from_hex")]
    pub aad: Vec<u8>,
    /// Plaintext.
    #[serde(deserialize_with = "from_hex")]
    pub pt: Vec<u8>,
    /// Ciphertext, without the tag.
    #[serde(deserialize_with = "from_hex")]
    pub ct: Vec<u8>,
    /// 16-byte tag.
    #[serde(deserialize_with = "from_hex")]
    pub tag: Vec<u8>,
    /// `false` if decryption must fail.
    pub valid: bool,
}

/// Extendable-output function vector.
#[derive(Debug, Clone, Deserialize)]
pub struct XofVector {
    /// Unique vector id.
    pub id: String,
    /// Where the vector comes from.
    pub source: String,
    /// Input message.
    #[serde(deserialize_with = "from_hex")]
    pub msg: Vec<u8>,
    /// Expected output; its length is the requested output length.
    #[serde(deserialize_with = "from_hex")]
    pub out: Vec<u8>,
}

fn from_hex<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<u8>, D::Error> {
    hex::decode(String::deserialize(d)?).map_err(serde::de::Error::custom)
}

fn load<T: DeserializeOwned>(file: &str) -> CryptoResult<Vec<T>> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../test_data/kat_sources")
        .join(file);
    let vectors: Vec<T> = std::fs::read_to_string(&path)
        .map_err(|e| e.to_string())
        .and_then(|s| serde_json::from_str(&s).map_err(|e| e.to_string()))
        .map_err(|e| CryptoError::Default(format!("KAT vectors {file}: {e}")))?;
    if vectors.is_empty() {
        return Err(CryptoError::Default(format!(
            "KAT vectors {file}: no vector"
        )));
    }
    Ok(vectors)
}

/// AES-CMAC vectors: NIST SP 800-38B, CAVP, Wycheproof, OpenSSL.
pub fn aes_cmac_vectors() -> CryptoResult<Vec<MacVector>> {
    load("aes_cmac.json")
}

/// AES-GMAC vectors: OpenSSL (NIST, IEEE 802.1AE), and the empty-plaintext AES-GCM vectors.
pub fn aes_gmac_vectors() -> CryptoResult<Vec<MacVector>> {
    load("aes_gmac.json")
}

/// AES-GCM vectors: OpenSSL, NIST CAVP, Wycheproof.
pub fn aes_gcm_vectors() -> CryptoResult<Vec<AeadVector>> {
    load("aes_gcm.json")
}

/// SHAKE-256 vectors (FIPS 202, OpenSSL).
pub fn shake256_vectors() -> CryptoResult<Vec<XofVector>> {
    load("shake256.json")
}
